"""
Professional, deterministic email response generator for Cynbit LeadIQ.
Strictly template-based and rule-driven. Runs 100% locally with zero external LLM dependencies.
Clearly labeled as template-generated.
"""

from typing import Dict, List, Optional

DISCLAIMER_HEADER = (
    "--------------------------------------------------------------------------------\n"
    "[SYSTEM NOTICE: This is a deterministic, template-generated draft generated by\n"
    "Cynbit LeadIQ based on extracted requirements. It is NOT generated by an LLM.]\n"
    "--------------------------------------------------------------------------------\n\n"
)

CATEGORY_FOCUS_POINTS = {
    "AI/ML Solutions": (
        "Our specialized AI/ML engineering team routinely builds production-ready predictive "
        "models, custom NLP pipelines, and computer vision systems with robust MLOps on AWS and GCP."
    ),
    "Web Development": (
        "Our web development practice specializes in modern, scalable SaaS applications, "
        "high-performance frontend portals (React/Next.js), and resilient backend APIs (Python/FastAPI)."
    ),
    "Mobile Apps": (
        "Our mobile engineering team develops native and cross-platform applications (Flutter, React Native) "
        "engineered for offline resilience, biometrics, and seamless backend integration."
    ),
    "Automation & Workflows": (
        "Our intelligent automation group builds end-to-end data pipelines, custom RPA workflows, "
        "and integration bridges that eliminate manual operational bottlenecks."
    ),
    "Cloud & DevOps": (
        "Our cloud architects provide turnkey cloud migrations, container orchestration (Docker, Kubernetes), "
        "and Terraform-based infrastructure-as-code to maximize availability and optimize cost."
    ),
    "Other / Advisory": (
        "Cynbit provides senior technical advisory, architecture audits, and technology roadmap consulting "
        "to assist leadership in de-risking complex digital initiatives."
    )
}


def generate_lead_response(
    client_name: str,
    company: str,
    primary_category: str,
    timeline: str,
    budget_tier: str,
    detected_entities: List[str],
    response_type: str = "Standard Discovery",
    sender_name: str = "Cynbit Solutions Team",
    sender_title: str = "Client Solutions Director",
    meeting_link: str = "https://cynbit.com/schedule-discovery"
) -> Dict[str, str]:
    """
    Generates a tailored, professional response template incorporating lead attributes.
    Returns dictionary with 'subject', 'body', and 'notice'.
    """
    first_name = client_name.strip().split()[0] if client_name else "there"
    company_phrase = f" at {company}" if company and company != "Unspecified" else ""
    tech_phrase = f" (particularly regarding {', '.join(detected_entities[:3])})" if detected_entities else ""
    cat_summary = CATEGORY_FOCUS_POINTS.get(primary_category, CATEGORY_FOCUS_POINTS["Other / Advisory"])

    is_urgent = "immediate" in timeline.lower() or "< 2 weeks" in timeline.lower()
    is_budget_unclear = "low" in budget_tier.lower() or "unspecified" in budget_tier.lower()

    if response_type == "High-Urgency Fast-Track" or (response_type == "Auto-Select" and is_urgent):
        subject = f"Expedited Discovery: Cynbit Technical Consultation for {company if company != 'Unspecified' else client_name}"
        body = (
            f"Dear {first_name},\n\n"
            f"Thank you for reaching out to Cynbit regarding your upcoming {primary_category} project{company_phrase}.\n\n"
            f"We noted that your timeline is urgent ({timeline}). In order to support your launch schedule, "
            f"we have placed your inquiry on our priority consultation track.\n\n"
            f"{cat_summary}\n\n"
            f"Given your focus{tech_phrase}, we can arrange a direct 30-minute scoping call with one of our "
            f"Senior Solutions Architects within the next 24 to 48 hours to confirm requirements and milestones.\n\n"
            f"Please reserve a convenient time here: {meeting_link}\n\n"
            f"Best regards,\n\n"
            f"{sender_name}\n"
            f"{sender_title}\n"
            f"Cynbit Technologies\n"
        )

    elif response_type == "Budget & Scope Clarification" or (response_type == "Auto-Select" and is_budget_unclear):
        subject = f"Cynbit Consultation: Project Scope & Budget Alignment for {primary_category}"
        body = (
            f"Dear {first_name},\n\n"
            f"Thank you for contacting Cynbit regarding your {primary_category} initiative{company_phrase}.\n\n"
            f"To ensure we propose the most viable implementation approach for your requirements{tech_phrase}, "
            f"we would appreciate a few brief details regarding your initial target scope:\n"
            f"  1. Are you targeting an initial proof-of-concept (POC/MVP) or a production-ready deployment?\n"
            f"  2. Do you have an established budget envelope or target delivery milestone in mind?\n"
            f"  3. Are there existing technical assets or data sets already in place?\n\n"
            f"{cat_summary}\n\n"
            f"Once you share these parameters, we will gladly prepare a tailored capability overview and indicative roadmap.\n\n"
            f"Warm regards,\n\n"
            f"{sender_name}\n"
            f"{sender_title}\n"
            f"Cynbit Technologies\n"
        )

    elif response_type == "Technical Deep Dive":
        subject = f"Technical Discovery: {primary_category} Specifications for {company if company != 'Unspecified' else client_name}"
        body = (
            f"Dear {first_name},\n\n"
            f"Thank you for your detailed inquiry regarding Cynbit's {primary_category} capabilities.\n\n"
            f"Our engineering leadership has reviewed your notes{tech_phrase}. {cat_summary}\n\n"
            f"To prepare an actionable architecture overview before our introductory call, could you share:\n"
            f"  - Preferred hosting or cloud deployment environment (e.g. AWS, GCP, Azure, or on-prem)\n"
            f"  - Key third-party integrations, APIs, or legacy data sources\n"
            f"  - Any specific compliance or data security requirements\n\n"
            f"You may also select a direct time for a technical discovery session: {meeting_link}\n\n"
            f"Sincerely,\n\n"
            f"{sender_name}\n"
            f"{sender_title}\n"
            f"Cynbit Technologies\n"
        )

    else:  # Standard Discovery
        subject = f"Thank you for contacting Cynbit - {primary_category} Consultation"
        body = (
            f"Dear {first_name},\n\n"
            f"Thank you for your inquiry regarding {primary_category}{company_phrase}.\n\n"
            f"{cat_summary}\n\n"
            f"We would welcome the opportunity to discuss your goals{tech_phrase} and explore how our "
            f"engineering team can deliver tailored software solutions for your organization.\n\n"
            f"Please feel free to schedule an introductory discovery conversation at your convenience: {meeting_link}\n\n"
            f"Looking forward to speaking with you.\n\n"
            f"Best regards,\n\n"
            f"{sender_name}\n"
            f"{sender_title}\n"
            f"Cynbit Technologies\n"
        )

    full_text = DISCLAIMER_HEADER + f"Subject: {subject}\n\n" + body

    return {
        "subject": subject,
        "body": body,
        "full_text": full_text,
        "template_name": response_type,
        "notice": "Template-Generated (Non-LLM)"
    }
